import { useEffect, useState } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import {
  validateSignupVerificationToken,
  markEmailVerified,
  getEmailVerificationSession,
} from "../../services/emailVerificationApi";
import { storeAuthFromResponse } from "../../services/auth";

export default function EmailVerifyCallbackPage({ portal, nextPath }) {
  const navigate = useNavigate();
  const { uidb64, token: tokenParam } = useParams();
  const [searchParams] = useSearchParams();
  const token = tokenParam || searchParams.get("token");

  const [status, setStatus] = useState("loading");
  const [error, setError] = useState("");

  useEffect(() => {
    if (!uidb64 || !token) {
      setStatus("error");
      setError("Missing verification link parameters.");
      return;
    }

    let cancelled = false;
    (async () => {
      try {
        const data = await validateSignupVerificationToken(uidb64, token, portal);
        const email = data?.email || getEmailVerificationSession(portal)?.email || "";
        markEmailVerified(portal, email);
        if (data?.access) {
          storeAuthFromResponse(data, email);
        }

        // Dynamically resolve target onboarding setup path based on actual database role
        let targetPath = nextPath;
        if (data?.role) {
          const r = String(data.role).toLowerCase();
          if (r === "individual" || r === "professional") {
            targetPath = "/professional/onboarding/profile";
          } else if (r === "enterprise" || r === "business") {
            targetPath = "/onboarding/company";
          }
        } else {
          // Fallback to checking the portal/link type if role field is not available in mock/development mode
          if (portal === "professional") {
            targetPath = "/professional/onboarding/profile";
          } else {
            targetPath = "/onboarding/company";
          }
        }

        if (!cancelled) {
          navigate(targetPath, { replace: true, state: { email } });
        }
      } catch (err) {
        if (!cancelled) {
          setStatus("error");
          setError(
            err.response?.data?.detail ||
              err.response?.data?.message ||
              err.response?.data?.error ||
              "This verification link is invalid or has expired."
          );
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [uidb64, token, portal, nextPath, navigate]);

  if (status === "loading") {
    return (
      <div className="min-h-screen bg-cream flex items-center justify-center font-sans">
        <p className="text-sm text-gray-500">Verifying your email…</p>
      </div>
    );
  }

  const pendingRoute =
    portal === "professional" ? "/professional/onboarding/verify-email" : "/verify-email";

  return (
    <div className="min-h-screen bg-cream flex flex-col items-center justify-center px-6 font-sans text-center">
      <div className="bg-white rounded-2xl border border-red-100 p-8 max-w-md shadow-sm">
        <p className="text-sm text-red-600 mb-6">{error}</p>
        <button
          type="button"
          onClick={() => navigate(pendingRoute)}
          className="px-6 py-3 bg-navy text-white rounded-full text-sm font-medium hover:bg-navy/90"
        >
          Back to verification →
        </button>
      </div>
    </div>
  );
}
